const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $('SLA & Progress Engine').first().json;
const ai = String($input.first().json.text || '').trim();
const letter = ai || ('Chúc mừng ' + e.fullName + ' đã hoàn thành xuất sắc chương trình Onboarding 30 ngày và chính thức hòa nhập cùng đại gia đình công ty!');

const text = [
  '🎉 <b>CHÚC MỪNG HOÀN THÀNH 100% ONBOARDING 30 NGÀY!</b>', '',
  '🌟 Nhiệt liệt chúc mừng <b>' + esc(e.fullName) + '</b> (' + esc(e.deptName) + ') đã hoàn thành trọn vẹn lộ trình thử việc!', '',
  '📜 <b>Lời chúc từ Ban Lãnh đạo:</b>',
  '<i>' + esc(letter.slice(0, 1500)) + '</i>', '',
  '🤝 <i>HR sẽ liên hệ để sắp xếp buổi đánh giá thử việc 3 bên (Nhân viên, Quản lý, HR) và trao đổi các bước tiếp theo.</i>'
].join('\n').substring(0, 4000);

return [{ json: { telegramText: text, chatId: e.telegramChatId } }];

// WF-03 | Boi canh SLA & Cau hinh (Ho tro ca Cron 08:30 Thu 2 & Lenh test cURL)
const CONFIG = {
  TELEGRAM_CHAT_ID: '8928574834',
  WORKSPACE_URL: 'http://localhost:5173/workspace',
  ESCALATE_AFTER_DAYS: 7
};
try {
  const input = $input.first()?.json || {};
  const payload = input.body || input;
  return [{ json: {
    telegramChatId: CONFIG.TELEGRAM_CHAT_ID,
    workspaceUrl: CONFIG.WORKSPACE_URL,
    escalateAfterDays: CONFIG.ESCALATE_AFTER_DAYS,
    forceUserId: payload.forceUserId ? parseInt(payload.forceUserId, 10) : null,
    forceStatus: payload.forceStatus || null,
    mockDaysInCompany: payload.mockDaysInCompany ? parseInt(payload.mockDaysInCompany, 10) : null,
    timestamp: new Date().toISOString()
  } }];
} catch (err) {
  return [{ json: {
    telegramChatId: CONFIG.TELEGRAM_CHAT_ID,
    workspaceUrl: CONFIG.WORKSPACE_URL,
    escalateAfterDays: CONFIG.ESCALATE_AFTER_DAYS,
    forceUserId: null,
    forceStatus: null,
    mockDaysInCompany: null,
    timestamp: new Date().toISOString()
  } }];
}
